def portfolio_risk_assessment(portfolio: dict) -> float:
    '''
    Takes a dictionary where keys are stock names and values are dicts with 'prices' list and 'allocation' float.
    For each stock, calculates volatility using calculate_stock_volatility(prices),
    multiplies by allocation, and sums all weighted volatilities.
    Returns a float representing the total portfolio risk as a weighted sum.
    '''
    total_risk = 0.0
    for stock, data in portfolio.items():
        prices = data.get('prices', [])
        allocation = data.get('allocation', 0.0)
        volatility = calculate_stock_volatility(prices)
        total_risk += volatility * allocation
    return total_risk


